create policy dd_work_orders_provider_update on public.dd_work_orders for update to authenticated using (exists (select 1 from public.dd_job_assignments a where a.job_id = dd_work_orders.id and a.provider_id = private.dd_current_provider_id() and a.assignment_status = 'ACCEPTED')) with check (exists (select 1 from public.dd_job_assignments a where a.job_id = dd_work_orders.id and a.provider_id = private.dd_current_provider_id() and a.assignment_status = 'ACCEPTED'));
create policy dd_job_evidence_provider_insert_assigned on public.dd_job_evidence for insert to authenticated with check (provider_id = private.dd_current_provider_id() and exists (select 1 from public.dd_job_assignments a where a.job_id = dd_job_evidence.job_id and a.provider_id = private.dd_current_provider_id() and a.assignment_status = 'ACCEPTED'));
create policy dd_job_evidence_provider_update_assigned on public.dd_job_evidence for update to authenticated using (provider_id = private.dd_current_provider_id() and exists (select 1 from public.dd_job_assignments a where a.job_id = dd_job_evidence.job_id and a.provider_id = private.dd_current_provider_id() and a.assignment_status = 'ACCEPTED')) with check (provider_id = private.dd_current_provider_id() and exists (select 1 from public.dd_job_assignments a where a.job_id = dd_job_evidence.job_id and a.provider_id = private.dd_current_provider_id() and a.assignment_status = 'ACCEPTED'));
create policy dd_change_orders_provider_read_accepted on public.dd_change_orders for select to authenticated using (exists (select 1 from public.dd_job_assignments a where a.job_id = dd_change_orders.job_id and a.provider_id = private.dd_current_provider_id() and a.assignment_status = 'ACCEPTED'));
create policy dd_completion_reviews_provider_read_assigned on public.dd_completion_reviews for select to authenticated using (exists (select 1 from public.dd_job_assignments a where a.job_id = dd_completion_reviews.job_id and a.provider_id = private.dd_current_provider_id() and a.assignment_status = 'ACCEPTED'));
